format2 <- function(x, max_digits = 40L) {
  x_chr_fixed <- format(
    x,
    scientific = FALSE,
    trim = TRUE,
    digits = 22
  )
  digit_count <- nchar(gsub("[^0-9]", "", x_chr_fixed))
  ifelse(
    is.na(x),
    NA_character_,
    ifelse(
      digit_count > max_digits,
      format(x, scientific = TRUE, trim = TRUE),
      x_chr_fixed
    )
  )
}

format_probability <- function(x) {
  if (is.na(x) || !is.finite(x)) {
    return("")
  }
  if (x > 0 && x < 0.01) {
    return("<0.01")
  }
  if (x < 1 && x > 0.995) {
    return(">0.99")
  }
  sprintf("%.2f", x)
}

