      options = list(
        ggiraph::opts_sizing(rescale = FALSE),
        ggiraph::opts_hover(css = "fill:black; r:5px;"),
        ggiraph::opts_tooltip(
          css = "background-color: white; border: 1px solid #999; padding: 6px; border-radius: 4px;"
        )
